mapper.select:
select c.province, c.city,c.description ,c.enabled_flag,fp.description as prodesc ,c.provincial_capital_flag from fnd_city c , fnd_province fp where c.province = fp.province
and c.province = #{province,jdbcType=VARCHAR}
and c.description like concat(concat('%',#{description,jdbcType=VARCHAR}),'%')
and c.city like concat(concat('%',#{city,jdbcType=VARCHAR}),'%')
and c.enabled_flag = #{enabledFlag,jdbcType=VARCHAR}

select c.* from fnd_city c , fnd_province fp where c.province = fp.province
and (c.province = #{province,jdbcType=VARCHAR} or fp.description = #{province,jdbcType=VARCHAR})
and c.enabled_flag = #{enabledFlag,jdbcType=VARCHAR}
